SELECT (DATE_TRUNC('DAY', "USAGE_DAY")) AS "TIME_BUCKET", SUM(SPEND_IN_CURRENCY) AS "ORG_ACCOUNT_SPEND" FROM (SELECT "ACCOUNT_NAME" AS ACCOUNT_NAME, "ORGANIZATION_NAME" AS ORGANIZATION_NAME, CAST("USAGE_DATE" AS DATE) AS USAGE_DAY, "USAGE_TYPE" AS USAGE_TYPE, "CURRENCY" AS CURRENCY, (CAST("USAGE" AS DECIMAL(38, 9))) AS USAGE_UNITS, (CAST("USAGE_IN_CURRENCY" AS DECIMAL(38, 9))) AS SPEND_IN_CURRENCY FROM usage_in_currency_daily) AS base GROUP BY (DATE_TRUNC('DAY', "USAGE_DAY")) ORDER BY "ORG_ACCOUNT_SPEND" DESC NULLS LAST, "TIME_BUCKET" LIMIT 100
